mapper.select:
select psn.*
from bus_rel_psn psn
where psn.DELFLAG_ = '1'

    and psn.name_ like concat(concat('%',#{name}),'%')


    and psn.status like #{status}


    and psn.identify_type like #{identifyType}


    and psn.TRANSACTION_DEP like #{transactionDep}


    and psn.identify_number like concat(concat('%',#{identifyNumber}),'%')


    and psn.domestic_or_foreign like #{domesticOrForeign}


    and psn.OPERATOR like concat(concat('%',#{operator}),'%')


    and psn.effect_relation like #{effectRelation}


    and DATE_FORMAT(psn.CREATED_TIME_, '%Y-%m-%d') like DATE_FORMAT(#{createTime}, '%Y-%m-%d')


    and DATE_FORMAT(psn.MODIFIED_TIME_, '%Y-%m-%d') like DATE_FORMAT(#{modifiedTime}, '%Y-%m-%d')


    and psn.is_black like #{isBlack}


    and psn.data_source like #{dataSource}


    and psn.mger_org = #{mgerOrg}























ORDER BY MODIFIED_TIME_ DESC

select pid,name,identify_type,identify_number,shareholders_code from bus_rel_psn
where 1=1

    and name= #{name}


    and identify_type= #{identifyType}


    and identify_number= #{identifyNumber}


    and shareholders_code= #{shareholdersCode}


    and data_source= #{dataSource}

and DELFLAG_=1

select pid,name,identify_type,identify_number,shareholders_code from bus_rel_psn_suspect
where 1=1

    and name= #{name}


    and identify_type= #{identifyType}


    and identify_number= #{identifyNumber}


    and shareholders_code= #{shareholdersCode}

and DELFLAG_=1

        SELECT
        b.pid,
        b.name_,
        b.domestic_or_foreign domesticOrForeign,
        b.mger_org mgerOrg,
        b.identify_type identifyType,
        b.identify_number identifyNumber,
        b.regulator_oth1 regulatorOth1,
        b.is_black isBlack,
        r.to_type type
        FROM
        bus_rel_psn b
        JOIN bus_rel r ON r.to_pid = b.pid
        WHERE
        1=1
        
            and regulator_oth1= #{regulatorOth1}
            group by identifyNumber
        
        
            AND r.from_type = #{type}
            AND r.to_type = 'PSN'
            AND r.from_pid = #{pid}
        
        
            and rel_category= #{relCategory}
        
        
            and rel_category_sub= #{relCategorySub}
        
        
            and is_black= #{isBlack}
        
        
            and mem_group= #{memGroup}
        
        
            and group_name= #{groupName}
        
        
            and state_owned= #{stateOwned}
        
        AND r.DELFLAG_ = '1'
        AND r.rel_status = '00'
        UNION ALL
        SELECT
        b.pid,
        b.org_name,
        b.domestic_or_foreign domesticOrForeign,
        b.mger_org mgerOrg,
        b.identify_type identifyType,
        b.unisc_code uniscCode,
        b.regulator_oth1 regulatorOth1,
        b.is_black isBlack,
        r.to_type type
        FROM
        bus_rel_org b
        JOIN bus_rel r ON r.to_pid = b.pid
        WHERE
        1=1
        
            and regulator_oth1= #{regulatorOth1}
            group by uniscCode
        
        
            AND r.from_type = #{type}
            AND r.to_type = 'PSN'
            AND r.from_pid = #{pid}
        
        
            and rel_category= #{relCategory}
        
        
            and rel_category_sub= #{relCategorySub}
        
        
            and is_black= #{isBlack}
        
        
            and mem_group= #{memGroup}
        
        
            and group_name= #{groupName}
        
        
            and state_owned= #{stateOwned}
        
        AND r.DELFLAG_ = '1'
        AND r.rel_status = '00'
